source='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    exterior = set()
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and (r, c) not in exterior:
                exterior.add((r, c)); q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and (r, c) not in exterior:
                exterior.add((r, c)); q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr,nc) not in exterior:
                exterior.add((nr,nc)); q.append((nr,nc))
    inside = {(r,c) for r in range(h) for c in range(w)
              if grid[r][c] == 0 and (r,c) not in exterior}
    out = [row[:] for row in grid]
    unseen = set(inside)
    color_by_inner_width = {3: 8, 5: 4, 7: 3}
    while unseen:
        start = unseen.pop()
        comp = {start}
        stack = [start]
        while stack:
            r,c = stack.pop()
            for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if (nr,nc) in unseen:
                    unseen.remove((nr,nc)); comp.add((nr,nc)); stack.append((nr,nc))
        width = max(c for r,c in comp) - min(c for r,c in comp) + 1
        color = color_by_inner_width.get(width, 8)
        for r,c in comp:
            out[r][c] = color
    return out
'''
